import React from 'react';
import { TimePicker, FormItem } from '@storage-fe/formily-arco';
import { createForm } from '@formily/core';
import { FormProvider, Field } from '@formily/react';

const form = createForm();

export default () => (
  <FormProvider form={form}>
    <Field name="timePicker" title="时间选择器" decorator={[FormItem]} component={[TimePicker]} />
    <Field name="timeRangePicker" title="时间范围选择器" decorator={[FormItem]} component={[TimePicker.RangePicker]} />
  </FormProvider>
);
